sys_ui_policy.script_false:
function onCondition() {
    for (var i = 1; i <= 5; i++) {
        var field = 'cotl_task_parent.docking_' + i;
        g_form.setDisplay(field, false);
        g_form.setReadOnly(field, false);
        g_form.setMandatory(field, false);
    }
}

sys_ui_policy.script_true:
function onCondition() {
    var check = new GlideAjax('x_hccc_cotl.Hoc_CotlUtilsAjax');
    check.addParam('sysparm_name', 'checkFieldValuedocking');
    check.addParam('sysparm_parentfield', g_form.getValue('worksheet'));

    check.getXMLAnswer(function(answer) {
        var result = JSON.parse(answer || '{}');
        var readonlyFields = result.readonly || [];
        var editableFields = result.editable || [];

        for (var i = 1; i <= 5; i++) {
            g_form.setDisplay('docking_' + i, false);
            g_form.setReadOnly('docking_' + i, false);
            g_form.setMandatory('docking_' + i, false);

            g_form.setDisplay('cotl_task_parent.docking_' + i, false);
            g_form.setReadOnly('cotl_task_parent.docking_' + i, false);
            g_form.setMandatory('cotl_task_parent.docking_' + i, false);
        }

        readonlyFields.forEach(function(fieldp) {
            var val = g_form.getValue('cotl_task_parent.' + fieldp);
            if (val) {
                g_form.setDisplay('cotl_task_parent.' + fieldp, true);
            }
        });
        readonlyFields.forEach(function(fieldchild) {
            var val = g_form.getValue(fieldchild);
            if (val) {
                g_form.setDisplay(fieldchild, true);
            }
        });

        editableFields.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setReadOnly(field, false);
            g_form.setMandatory(field, true);
        });
    });
}
